"use strict";(globalThis.webpackChunkconduction_website=globalThis.webpackChunkconduction_website||[]).push([[7136],{6219(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>i,default:()=>d,frontMatter:()=>r,metadata:()=>a,toc:()=>l});var a=o(6321),n=o(4848),s=o(8453);const r={slug:"the-platform-moment",title:"Nextcloud is a platform",contentType:"opinion",authors:["ruben"],date:new Date("2026-05-19T00:00:00.000Z"),summary:"A thinkpiece on why Nextcloud should be viewed as a platform, not a product. The sovereign-workplace bundles are the start, not the finish. Microsoft has eighteen to thirty-six months. So does Europe.",tags:["Nextcloud","Platform","Sovereignty","AI"],durationMinutes:7},i=void 0,h={authorsImageUrls:[void 0]},l=[{value:"The pattern",id:"the-pattern",level:2},{value:"Why Nextcloud sits in this position",id:"why-nextcloud-sits-in-this-position",level:2},{value:"The bundle is not the workspace",id:"the-bundle-is-not-the-workspace",level:2},{value:"AI as substrate, not as a checkbox",id:"ai-as-substrate-not-as-a-checkbox",level:2},{value:"The Microsoft clock",id:"the-microsoft-clock",level:2},{value:"What needs to be true",id:"what-needs-to-be-true",level:2},{value:"A personal note",id:"a-personal-note",level:2}];function c(e){const t={a:"a",h2:"h2",p:"p",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"The same pattern shows up every time a software category goes through its platform moment. WordPress in 2011. Salesforce a few years earlier. Atlassian after that. The iPhone, in the consumer space, before any of them. Each one started life as a product. Each one became a platform. The companies that managed the transition own their category two decades later. The ones that did not are footnotes."}),"\n",(0,n.jsx)(t.p,{children:"I think Nextcloud is in front of that transition right now, and I do not think the field around it has noticed yet."}),"\n","\n",(0,n.jsx)(t.h2,{id:"the-pattern",children:"The pattern"}),"\n",(0,n.jsx)(t.p,{children:"What turns a product into a platform is not a feature release. It is a reframe."}),"\n",(0,n.jsx)(t.p,{children:"WordPress core stayed deliberately small while the plugin ecosystem grew into a multi-billion-euro marketplace. The plugin layer became the actual product. WordPress core became infrastructure. By 2020 you could not pick anything else for anything except enterprise CMS or proprietary SaaS, not because WordPress had won on features, but because the ecosystem around it had."}),"\n",(0,n.jsx)(t.p,{children:"Salesforce AppExchange shipped in 2006. By the late 2010s, 91% of Salesforce customers were using at least one app from it. That is the actual moat under the company. Competitors do not just have to beat the CRM. They have to beat the CRM plus six thousand integrations. The AppExchange partners collectively earn multiples of what Salesforce earns directly from the marketplace. Both win in the same outcome."}),"\n",(0,n.jsx)(t.p,{children:'The iPhone won smartphones not by being a better phone. It won by being declared "the platform that runs apps" before that was technically true. By 2010 every other platform either copied the App Store model or died. The naming preceded the platform reality by years. The naming was load-bearing.'}),"\n",(0,n.jsx)(t.p,{children:"SharePoint is the cautionary case. Microsoft positioned it as the platform for a decade. The technical surface supported it. The marketing budget supported it. The architecture and the economics did not. SharePoint never produced an ecosystem. It stayed a product. Power Platform displaced it as Microsoft's positioned platform for business apps."}),"\n",(0,n.jsx)(t.p,{children:"Five cases. One pattern. Each one is the same shape."}),"\n",(0,n.jsx)(t.h2,{id:"why-nextcloud-sits-in-this-position",children:"Why Nextcloud sits in this position"}),"\n",(0,n.jsx)(t.p,{children:"The substrate for a workplace platform sits in Nextcloud Hub today. It just is not framed as substrate."}),"\n",(0,n.jsx)(t.p,{children:"Files. Calendar. Contacts. Talk. Mail. An identity layer that already speaks LDAP, SAML, and OIDC. A permission model that runs across all of them. Every business app needs these primitives. Nextcloud ships them already integrated, in one product, with one access control surface. ExApps adds the second piece: a production-grade pattern for running anything, in any language, as an integrated app inside the workspace. Two to three hundred thousand servers. Several hundred apps in the store. ISO 27001. Blauer Engel. EU data hosting by default. None of these are decisions still to be made. They already shipped."}),"\n",(0,n.jsx)(t.p,{children:"The sovereign-workplace push around openDesk, Mijn Bureau, La Suite Num\xe9rique, and the Bechtle-Nextcloud offering uses Nextcloud as a core component. Schleswig-Holstein moved 40,000 civil servants off Microsoft in October 2025 with openDesk as the collaboration layer. The Bundeswehr signed a seven-year agreement. The Robert Koch Institute and the International Criminal Court run on it. The deployments are real and at scale."}),"\n",(0,n.jsx)(t.p,{children:"What none of those bundles do, yet, is frame Nextcloud as the platform underneath the suite. They frame it as one of several components in a bundle. The frame is correct for the moment of cutover from Microsoft. It will not be correct three years later."}),"\n",(0,n.jsx)(t.h2,{id:"the-bundle-is-not-the-workspace",children:"The bundle is not the workspace"}),"\n",(0,n.jsx)(t.p,{children:'Year one, a buyer asks "can I replace Microsoft." Year three, they ask "where does my organisation run."'}),"\n",(0,n.jsx)(t.p,{children:"A bundle answers the first question. It does not answer the second. A bundle ships a fixed set of tools, with the integration between them happening in the user's head or in their browser tabs. A workspace is a different thing: the unified surface where people work, with the platform underneath it that hosts everything else. Tools, data, AI, the hundreds of small workflows every organisation runs that are too small for IT to formalise and too operational to outsource. Leave requests. Equipment loans. Visitor registration. Hardware inventory. Vendor onboarding. The long tail."}),"\n",(0,n.jsx)(t.p,{children:"The vendor that answers year three wins the relationship. Nextcloud-as-bundle does not. Nextcloud-as-platform does. That reframe is the thing I think is overdue."}),"\n",(0,n.jsx)(t.h2,{id:"ai-as-substrate-not-as-a-checkbox",children:"AI as substrate, not as a checkbox"}),"\n",(0,n.jsx)(t.p,{children:"AI changes the calculus on local data, and not in the direction most workplace vendors want it to."}),"\n",(0,n.jsx)(t.p,{children:"Microsoft Copilot routes user data to Azure for inference. Google Workspace does the same, to Google Cloud. Both have built sovereign-cloud variants \u2014 Bleu in France through a Capgemini and Orange joint venture, Delos in Germany through SAP and Telekom, Microsoft Cloud for Sovereignty as the umbrella programme \u2014 and these variants are serious engineering efforts. They reduce the surface of exposure. They do not eliminate it. The CLOUD Act still applies to Microsoft itself, even when European partners operate the infrastructure. The structural problem is jurisdictional, not contractual."}),"\n",(0,n.jsx)(t.p,{children:"For most market segments, the partial-sovereignty pitch will be enough. For the buyers who chose openDesk and Mijn Bureau specifically because the architecture matters, it will not be. They picked the suite path for a reason."}),"\n",(0,n.jsx)(t.p,{children:"An open workplace architecture inverts the problem. The data is already on infrastructure the customer controls. The AI substrate comes to the data, not the other way around. Local LLM endpoints. Retrieval indexing across the workspace. Tools that expose registers to models under the user's session, audit-logged at every step, with the operator choosing the model. Mistral on-premise. A self-hosted Llama variant. Or, where policy allows, a commodity API. The architecture supports the operator's policy choices, not the vendor's."}),"\n",(0,n.jsx)(t.p,{children:"The features are competitive. The architecture is structurally different. The structural difference shows up in every procurement evaluation that takes sovereignty seriously. This is the part where Nextcloud's position compounds. Microsoft cannot win on sovereignty for the buyers who care most about it. Microsoft can absolutely win on time-to-value and ecosystem depth, which is what they are spending five years and significant capital trying to do. The race is over which structural advantage matters more for which buyer."}),"\n",(0,n.jsx)(t.h2,{id:"the-microsoft-clock",children:"The Microsoft clock"}),"\n",(0,n.jsx)(t.p,{children:'A bit of context on the size of the other side. Power Platform was at 33 million monthly active users in 2023. 48 million in 2024. 56 million in 2025. Microsoft has named 500 million by the end of the decade as their public target. 97% of Fortune 500 companies use Power Platform in some capacity. The 2026 release wave unifies Power Apps, Power Automate, Power Pages, Copilot Studio, and Dataverse into one AI-native citizen-developer story. The framing they use internally is "low code is dead": apps start as conversations with Copilot and quietly become React.'}),"\n",(0,n.jsx)(t.p,{children:"Europe has, by my read, somewhere between eighteen and thirty-six months to ship a credible architectural answer. After that window closes, citizen developers in European organisations will have trained on the Microsoft stack, and switching costs become real in a way no sales motion fixes. Mindshare is the most important window. It is the one that closes the fastest."}),"\n",(0,n.jsx)(t.h2,{id:"what-needs-to-be-true",children:"What needs to be true"}),"\n",(0,n.jsxs)(t.p,{children:["The architectural answer exists in pieces. The sovereign-workplace bundles are one piece. Open-source workflow tools \u2014 Windmill, n8n, OpenProject \u2014 are another. Open-weight LLMs hosted in Europe are a third. The composition layer that lets a non-developer in a municipality ship a leave-request app in an afternoon is the piece most still missing in production. It is the piece we are building at Conduction, in the open, as ",(0,n.jsx)(t.a,{href:"/apps/openbuilt",children:"OpenBuilt"}),". It is not the only such piece that needs to ship. It is one."]}),"\n",(0,n.jsx)(t.p,{children:"The other thing that needs to be true is naming. Steve Jobs did not market the iPhone as a phone with extensible features. He positioned it as the platform that runs apps, years before the platform reality fully shipped. The naming was load-bearing. It still is."}),"\n",(0,n.jsx)(t.p,{children:"Nextcloud-as-platform is true today in every structural sense that matters. What is missing is for the company, the ecosystem, and the buyers to all describe it that way out loud."}),"\n",(0,n.jsx)(t.h2,{id:"a-personal-note",children:"A personal note"}),"\n",(0,n.jsx)(t.p,{children:"I have spent four quarters of my company's runway building toward this view. It is not a quiet view. I am writing it down because I think the architectural argument is settled, the competitive window is open, and the next move belongs to people who can see the shape of the moment clearly. That includes Nextcloud's team. That includes the buyers running European sovereign-workplace migrations. That includes peer companies in the open-source workplace stack."}),"\n",(0,n.jsxs)(t.p,{children:["If you read this and disagree, I would genuinely like to hear why. ",(0,n.jsx)(t.a,{href:"mailto:ruben@conduction.nl",children:"ruben@conduction.nl"}),"."]})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},6321(e){e.exports=JSON.parse('{"permalink":"/academy/the-platform-moment","source":"@site/academy/2026-05-19-the-platform-moment/index.mdx","title":"Nextcloud is a platform","description":"The same pattern shows up every time a software category goes through its platform moment. WordPress in 2011. Salesforce a few years earlier. Atlassian after that. The iPhone, in the consumer space, before any of them. Each one started life as a product. Each one became a platform. The companies that managed the transition own their category two decades later. The ones that did not are footnotes.","date":"2026-05-19T00:00:00.000Z","tags":[{"inline":true,"label":"Nextcloud","permalink":"/academy/tags/nextcloud"},{"inline":true,"label":"Platform","permalink":"/academy/tags/platform"},{"inline":true,"label":"Sovereignty","permalink":"/academy/tags/sovereignty"},{"inline":true,"label":"AI","permalink":"/academy/tags/ai"}],"readingTime":7.31,"hasTruncateMarker":true,"authors":[{"name":"Ruben van der Linde","title":"CTO, Conduction","url":"https://github.com/rubenvdlinde","page":{"permalink":"/academy/authors/ruben"},"socials":{"github":"https://github.com/rubenvdlinde","email":"mailto:ruben@conduction.nl"},"imageURL":"https://github.com/rubenvdlinde.png","key":"ruben"}],"frontMatter":{"slug":"the-platform-moment","title":"Nextcloud is a platform","contentType":"opinion","authors":["ruben"],"date":"2026-05-19T00:00:00.000Z","summary":"A thinkpiece on why Nextcloud should be viewed as a platform, not a product. The sovereign-workplace bundles are the start, not the finish. Microsoft has eighteen to thirty-six months. So does Europe.","tags":["Nextcloud","Platform","Sovereignty","AI"],"durationMinutes":7},"unlisted":false,"prevItem":{"title":"OpenWoo community \u2014 two years of monthly meetings","permalink":"/academy/openwoo-community-meetings"},"nextItem":{"title":"Build a Nextcloud app on the Conduction stack \u2014 Part 4: Knowledge + ship","permalink":"/academy/deskdesk-tutorial-4-knowledge-and-ship"}}')}}]);